import { PLAN_LIMITS } from '@/features/billing/plans';
import { TEMPLATES } from '@/features/invitations/templates/registry';
import { he } from '@/lib/i18n/app.he';
import type { Feature } from '@/features/flags/features';
import { TICKETS } from './tickets/config';

/** What the assistant's manual needs to know about this deployment (prices come from its settings). */
export interface KnowledgeContext {
  brand: string;
  site: string;
  prices: { pro: number; business: number };
  messagePrice: number;
  packs: { count: number; price: number }[];
  supportEmail: string;
}

/**
 * Where the manual documents each feature (features/flags FEATURES): a phrase that must appear in
 * knowledgeBase(). Typed as Record<Feature, …>, so a new feature doesn't compile until it's documented
 * here, and tests/unit/support.test.ts checks each phrase is really in the manual.
 */
export const MANUAL_COVERAGE: Record<Feature, string> = {
  cinematic: 'עיצוב קולנועי',
  seating: 'סידור שולחנות',
  seating_auto: 'סידור אוטומטי',
  seating_guide: 'מספר השולחן',
  checkin: 'רישום בכניסה',
  live_gallery: 'גלריה חיה',
  gallery_ai: 'בדיקה אוטומטית של התוכן',
  projector: 'מסך באולם',
  face_albums: 'התמונות שאני בהן',
  auto_reel: 'סרט הרגעים',
  languages: 'משבע השפות',
  translate_ai: 'תרגום אוטומטי',
  voice: 'הקראת ההזמנה',
  art_direction: 'עצבו לי',
  draft_review: 'עיון המשפחה',
  analytics: 'תובנות',
  planning: 'תכנון האירוע',
  planning_ai: 'הצעה לפי תיאור',
  planning_export: 'ייצוא ל-Excel',
  planning_templates: 'שמירת תוכנית כתבנית',
};

const f = PLAN_LIMITS.free;
const p = PLAN_LIMITS.pro;
const b = PLAN_LIMITS.business;

/**
 * The support assistant's manual: every capability of the product, where it is and how to use it, in
 * Hebrew (the assistant answers in the user's language). Kept in sync with the product — when a
 * feature changes, change it here too (tests/unit/support.test.ts checks the key facts).
 */
export function knowledgeBase(c: KnowledgeContext): string {
  const packs = c.packs.map((x) => `${x.count} הודעות ב־₪${x.price}`).join(', ');
  // every public design, read from the registry: the list is never out of date (an unlisted one —
  // manifest `listed: false` — is the admins' until it is released)
  const listed = [...TEMPLATES.values()].filter(({ manifest }) => manifest.listed);
  const designs = listed
    .map(({ manifest: m }) => {
      const events = m.categories.map((type) => he.eventTypes[type]).join(', ');
      return `${m.name.he} (${m.name.en})${m.tier === 'premium' ? ' — פרימיום' : ''}: ${events}`;
    })
    .join('; ');
  return `
# ${c.brand} — המדריך המלא (בשביל העוזר)

${c.brand} (${c.site}) היא מערכת ליצירת הזמנות דיגיטליות לאירועים, בעברית ובאנגלית, עם אישורי הגעה, רשימת מוזמנים ושליחה בוואטסאפ. המשתמשים הם "מארחים" (מי שמזמין); "אורחים" או "מוזמנים" הם מי שמקבל את ההזמנה.

## 1. התחלה
- הרשמה: בעמוד הבית "יצירת הזמנה בחינם", או /signup — מייל וסיסמה (לפחות 8 תווים), או כניסה עם Google אם מופעלת. מי שבחר חבילה בעמוד המחירים ממשיך אחרי ההרשמה ישר לתשלום עליה. שכחתם סיסמה: בעמוד הכניסה "שכחתי סיסמה" שולח קישור לאיפוס.
- קישורים מהמייל (אישור הרשמה, איפוס סיסמה) עובדים פעם אחת ולזמן מוגבל: קישור שפג תוקפו או שכבר נוצל — נכנסים לחשבון, או מבקשים קישור חדש ב"שכחתי סיסמה". קישור לאיפוס סיסמה צריך לפתוח באותו דפדפן שבו ביקשו אותו; קישור לאישור הרשמה שנפתח בדפדפן אחר כבר אישר את המייל — רק נכנסים.
- אחרי הכניסה: "האירועים שלי" (/app/invitations). במחשב יש סרגל צד: "+ אירוע חדש", "האירועים שלי", "מדריך ועזרה" (פותח את חלון העזרה), שפת הממשק (עב/EN), "מראה" (בהיר / כהה / לפי המכשיר), ותפריט החשבון למטה — בו החשבון שלי, חבילה וחיובים, "תמיכה" (הפניות לצוות; נקודה על העיגול כשהצוות ענה), "שאלו את העוזר", יצירת קשר ויציאה; וקישורים למדיניות. "מחפשים מקום לאירוע?" (אולמות ב־Badook Events, event.badooks.com) נמצא עכשיו ככרטיס במסך "ספקים" של האירוע, כל עוד לא סגרתם אולם. בטלפון יש סרגל עליון קטן וסרגל תחתון: אירועים · חדש · חבילה · עזרה; "מראה" ושפת הממשק נמצאים בתפריט החשבון (העיגול עם האות למעלה), והקישורים למדיניות — בתחתית כל עמוד.
- מצב כהה: "מראה" → "כהה" (או "לפי המכשיר" — עובר לבד לפי הגדרת הטלפון או המחשב). הבחירה נשמרת בדפדפן הזה. היא חלה על המערכת (ההזמנות, העורך, החבילה, החשבון, התמיכה, סביבת הניהול); ההזמנה עצמה שהאורחים רואים נשארת בעיצוב שלה, וגם דף הבית, דפי הכניסה והמדיניות. מה שמדפיסים (תוכנית ההושבה, כרטיסי השולחן) יוצא תמיד בהיר.
- בכל אזור במערכת יש כפתור "?" שמסביר מה כל כפתור באזור עושה, ומעבר עם העכבר על כפתור מציג הסבר קצר. בתחתית ההסבר: "במדריך" (פותח את המאמר של המסך הזה במדריך) ו"שאלו את העוזר".
- עזרה: כפתור אחד — "מדריך ועזרה" בסרגל הצד (בטלפון: "עזרה" בסרגל התחתון, וגם הכפתור הצף בפינה) — פותח חלון עזרה עם שלוש לשוניות: "מדריך" (מאמרים קצרים בצעדים, לפי שלבי האירוע, עם חיפוש ו"שאלות נפוצות"; קודם המאמרים של המסך הנוכחי), "שאלו את העוזר" (הצ׳אט הזה) ו"פנייה לצוות" (פנייה חדשה, הפניות שלי, יצירת קשר). המדריך המלא גם בעמוד /app/guide. בראש המדריך (ובלשונית "מדריך" של חלון העזרה) יש "סיור מלא במערכת" — סרטון של כמה דקות שמראה את כל היכולות לפי הסדר, עם כתוביות בעברית; גם "צפו עם קול" על הסרטון הקצר (ברשימת האירועים הריקה, בבית של אירוע חדש ובאשף "אירוע חדש") פותח אותו. בעורך העוזר בסרגל העליון (בטלפון: בתפריט ⋯). השיחה נשמרת רק בלשונית הפתוחה; "שיחה חדשה" מתחיל מחדש.

## 2. יצירת הזמנה
- "אירוע חדש" פותח קודם שלוש שאלות קצרות (מסך מלא, "דילוג לגלריית העיצובים" תמיד זמין): 1) איזה אירוע חוגגים; 2) "מה אתם צריכים לאירוע?" — מסמנים אחד או כמה כלים: "הזמנה דיגיטלית ואישורי הגעה" (מסומן מראש), "תכנון האירוע" (משימות, תקציב וספקים), "סידור שולחנות", "יום האירוע" (עמדת כניסה, גלריה חיה, סרט). לא כל אירוע צריך הכול — מי שרוצה רק הזמנה דיגיטלית לא יראה משימות ותקציב; 3) שמות, תאריך, כמה אורחים בערך, ותקציב משוער (רק כשבחרו תכנון). עם הזמנה דיגיטלית — ממשיכים לגלריית העיצובים מסוננת לפי סוג האירוע, והפרטים כבר ממולאים; בלי הזמנה (למשל רק תכנון או רק שולחנות) — האירוע נוצר מיד עם עיצוב מתאים לסוג האירוע ונפתח בית האירוע. את הכלים משנים בכל רגע: "הוספה או הסרה של כלים" בסרגל האירוע (נפתח בכל מסך של האירוע), "צריכים עוד משהו?" בבית האירוע; הורדת כלי רק מסתירה אותו, שום דבר לא נמחק. בגלריה אפשר לסנן לפי סוג אירוע (חתונה, אירוסין, חינה, בר/בת מצווה, ברית, בייבי שאוור, יום הולדת, אירוע חברה, Save the Date), לפתוח תצוגה מקדימה חיה של עיצוב (כולל בחירת צבעים וגופנים), ו"דמו חי בלשונית חדשה". בכניסה הראשונה לבית האירוע יש סיור קצר של שלוש תחנות.
- עיצובים שמסומנים "פרימיום" אפשר לערוך בכל חבילה, אבל לפרסם רק בחבילות Pro ו־Business.
- "שימוש בעיצוב הזה" פותח אשף של 3 שלבים: 1) איזה אירוע חוגגים; 2) פרטי האירוע — שמות (לזוג: שני שמות; לבר/בת מצווה: שם החוגג/ת ושמות ההורים; ליום הולדת: שם וגיל), תאריך, שעה ואזור זמן; 3) שפות — עברית, אנגלית, רוסית, ערבית, צרפתית, ספרדית ואמהרית, אחת או כמה (ואיזו ראשית); עברית ואנגלית כלולות תמיד, השאר זמינות כשהאפשרות "שפות" פתוחה לאירוע. בסוף נוצרת טיוטה עם טקסטים מוכנים והעורך נפתח.
- בחבילה החינמית אפשר הזמנה פעילה אחת בכל זמן. כדי ליצור עוד: להעביר הזמנה ישנה לארכיון (בתפריט ⋯ של הכרטיס ברשימה) או לשדרג. ההזמנה המלאה שנוצרת מ־Save the Date לא נספרת בנפרד.
- ב"האירועים שלי" כל כרטיס מראה את הספירה לאחור ("היום!" ביום האירוע), כמה שלבים מהמסלול הושלמו (פס קטן), כמה אחוז ענו, מד תקציב קטן (כשיש תכנון ותקציב), את הצעד הבא (לחיצה עליו לוקחת ישר לשם), וכפתור גדול "כניסה לאירוע". לחיצה בכל מקום על הכרטיס פותחת את בית האירוע. מי שיש לו אירוע פעיל אחד בלבד נכנס אליו ישר; "כל האירועים" מציג את הרשימה. בסוף הרשימה כרטיס "אירוע חדש". בתפריט ⋯ של הכרטיס — כניסה לאירוע, עריכת העיצוב, מוזמנים, שיתוף, תשובות, "שכפול" ו"העברה לארכיון" (גם ב"הגדרות האירוע"). הזמנה בארכיון לא נמחקת ולא נספרת בחבילה; הכפתור "ארכיון" בראש הרשימה מציג אותן, ו"החזרה מהארכיון" מחזיר (כשיש מקום בחבילה).
- מרחב האירוע (/app/invitations/<מזהה>): במחשב סרגל הצד מתחלף לסרגל של האירוע — "כל האירועים", כרטיס האירוע, "בית האירוע", ואז "הכלים של האירוע" — רק הכלים שבחרו לאירוע, כל אחד עם סטטוס (✓ הושלם / "השבוע: N" / "בתהליך" / כמה לשליחה / "בעוד N ימים"): "תכנון האירוע" — משימות, תקציב, ספקים, פתקים ורעיונות; "ההזמנה והמוזמנים" — עיצוב ההזמנה (העורך במסך מלא), מוזמנים, שליחה ושיתוף, אישורי הגעה; "סידור שולחנות" (בלי הזמנה דיגיטלית — גם "מוזמנים" כאן); "ביום האירוע" — יום האירוע, גלריה חיה ומסך באולם, סרט הרגעים. לחיצה על שם הכלי פותחת או סוגרת את המסכים שלו; מתחת — "הוספה או הסרה של כלים" (תכנון, סידור שולחנות, יום האירוע); ולמטה תובנות, "הגדרות האירוע", "מדריך ועזרה" ותפריט החשבון. בטלפון — סרגל תחתון: בית האירוע והכלים, וכל כלי פותח חלונית עם המסכים שלו. בראש כל מסך פס קומפקטי: שמות, סטטוס, תאריך, ספירה לאחור, "פתיחת ההזמנה" / "פרסום ההזמנה" (בבית האירוע הפרסום הוא צעד במסלול). "חזרה" בעורך מחזירה לבית האירוע. "בית האירוע": למעלה האירוע (שם, תאריך, "בעוד N ימים", האם ההזמנה פורסמה והעתקת הקישור); "המסלול שלכם" — הצעדים לפי הכלים שבחרו (בהזמנה: מסיימים את העיצוב ומפרסמים ← מוסיפים מוזמנים או משתפים קישור כללי ← שולחים בוואטסאפ ← עוקבים אחרי אישורי ההגעה ותזכורות; בתכנון: פתיחת תוכנית, קביעת תקציב, משימות השבוע; שולחנות; יום האירוע — שבועיים לפני, ביום עצמו, ואחרי: סרט הרגעים), עם "X מתוך Y הושלמו", הצעד של עכשיו מודגש עם כפתור אחד ו"איך עושים את זה?" שפותח את המדריך; כשהאירוע רחוק (יותר מ־60 יום) התכנון קודם. "איך זה מתקדם" — רק כרטיסים שיש בהם מה להראות: אישורי הגעה אחרי שליחה, מד התקציב כשהוגדר, משימות השבוע. "צריכים עוד משהו?" — הכלים שלא נבחרו, ו"שינוי הכלים". "הגדרות האירוע": פרטי האירוע (בעורך), הכלים של האירוע, הגדרות התכנון, החבילה, שכפול והעברה לארכיון.
- איפה מעלים אקסל ושולחים בוואטסאפ: "ההזמנה והמוזמנים" ← "מוזמנים" (גם הצעד "מוסיפים את המוזמנים" או "שולחים בוואטסאפ" במסלול בבית האירוע מוביל לשם); או מתפריט ⋯ של כרטיס האירוע ← "מוזמנים".
- העיצובים (${listed.length}): ${designs}.

## 3. העורך
- מבנה: בצד — רשימת הסקשנים (לשונית "סקשנים") והגדרות העיצוב (לשונית "עיצוב"); במרכז — הטופס של מה שנבחר; ובצד השני — תצוגה מקדימה חיה בטלפון (אפשר להחליף לתצוגת מחשב). בטלפון העורך מתחלק למצבים: עריכה, תצוגה, וכל הסקשנים.
- שמירה אוטומטית: כל שינוי נשמר לבד ("כל השינויים נשמרו"). יש ביטול/חזרה (Undo/Redo), וגרסאות ושמירות קודמות שאפשר לראות ולשחזר ("גרסאות", סעיף 18).
- הסקשנים: מעטפה ופתיחה, המסך הראשי (המסך הראשון אחרי שהמעטפה נפתחת), ספירה לאחור, הסיפור שלנו, מקום האירוע (כתובת, מפה, Waze, Google Maps ותזכורת ביומן), סדר האירוע, הסעות, לינה, קוד לבוש, תפריט, פעילויות, טקסט חופשי, שאלות נפוצות, גלריה, מתנות (ביט, פייבוקס, העברה בנקאית וקישורים — האורחים מעתיקים בלחיצה), חשיפת התאריך (גירוד/לחיצה/סיבוב), אישור הגעה, וסיום — ועוד: ההורים, מתי (התאריך בגדול עם ספירה לאחור), איפה (מקום אחד בגדול), ציטוט (פסוק או שיר), וטקסט ותמונה. אפשר להוסיף סקשן ("הוספת סקשן"), לגרור לשינוי סדר, להסתיר (מתג) או למחוק. סקשן מוסתר לא מופיע לאורחים ולא נבדק בפרסום.
- מעטפה ופתיחה: אנימציית פתיחה עם חותם וראשי תיבות (אפשר לכבות). האורחים יכולים "לדלג". בכרטיס "פתיחה" בוחרים איך ההזמנה נפתחת: של העיצוב, מעטפה, שער, מסך (תיאטרון), זיקוקים, אבק זהב או חותם שעווה (נייר מובלט שהחותם שלו נשבר והדף נפתח לצדדים; צבע השעווה הוא צבע החותם) — לכל אחת תצוגה קטנה, והבחירה מתנגנת בתצוגה המקדימה ("הצגה מחדש"). השער והמסך נפתחים גם בגלילה. בעיצובים צילומיים הזיקוקים ואבק הזהב נפתחים מעל התמונה של המסך הראשי. טקסט ההנחיה של העיצוב מתנקה כשבוחרים פתיחה אחרת, כדי שתוצג ההנחיה של הפתיחה.
- עיצוב קולנועי (בכל החבילות; אפשר לכבות לאירוע): בכל סקשן — חוץ מהמסך הראשי והגלריה — יש אחרי התוכן כרטיסים: "תמונה או וידאו" (העלאה עם אחוזי התקדמות, או "מהתמונות של ההזמנה"; לוחצים על החלק החשוב בתמונה והוא יישאר במסגרת בכל מסך; לסרטון נשמרת תמונת פתיחה; "הכהיית התמונה" — אוטומטית או ידנית — שומרת על קריאות הטקסט), "פריסה" (רגיל, רקע מלא, תמונה בצד, תמונה בצד השני, פרלקסה, וידאו ברקע; פריסה שצריכה תמונה או סרטון זמינה רק אחריהם, ובסקשנים עם טופס, רשימה או מפה יש רק פריסות רקע), "תנועה" (כניסה: של העיצוב, הופעה, עלייה, ירידה, התקרבות, התרחקות, מהצד, מהצד השני, הטיה או בלי — כל אחת עם תצוגה חיה קטנה; בזמן הגלילה: פרלקסה או זום איטי לתמונה; חשיפת הטקסט: אותיות, מילים או שורות; עוצמה; "כיוון עדין" למשך, השהיה ומרחק; "הצגה" מנגן את התנועה בתצוגה המקדימה) ו"צבעי הסקשן" (כמו ההזמנה, רצועה כהה, רצועה רכה, בצבע ההדגשה או בחירה חופשית — עם מד ניגודיות ו"תיקון אוטומטי", "הצעות צבעים" מהתמונה של הסקשן, וגודל כותרת, מרווחים ופינות התמונה). במסך הראשי: תנועת הרקע וצבע הטקסט. "חזרה ל…" מחזיר כל כרטיס לעיצוב, והכל נכנס לביטול/חזרה.
- "סגנון ותנועה" (לשונית עיצוב): גודל הטקסט, המרווחים ועוצמת התנועה של כל ההזמנה ביחס לעיצוב; "בלי תנועה" — שום דבר לא זז, כמו אצל אורחים שביקשו להפחית תנועה.
- "הזמנה מונפשת" (בראש "סגנון ותנועה", בכל עיצוב): מתג "הרקע זז עם הגלילה" הופך את כל ההזמנה לסרט אחד — הרקע נשאר במקום, מתחלף בעדינות מתמונה לתמונה ומתקרב לאט בזמן שהאורחים גוללים, והטקסטים עולים מתוך ערפל. התמונה הראשונה היא של המסך הראשי (או הציור של העיצוב); כל סקשן שיש לו תמונה משלו (כרטיס "תמונה או וידאו") מביא רקע חדש, וסקשן בלי תמונה ממשיך את הרקע שלפניו. בכל תמונה בוחרים "התמונה ברקע" (מתקרבת, מתרחקת או בלי זום), "כיוון התנועה" (במקום, עולים, יורדים) ו"הכהיית התמונה". "מה מרחף מעל הרקע": פרפרים, עלי כותרת, אבק זהב או כלום. בהזמנה מונפשת הספירה לאחור נצמדת לראש המסך בזכוכית מט, וכפתור "אישור הגעה" מופיע בתחתית אחרי המסך הראשון. במחשב ההזמנה מוצגת במסגרת של טלפון מעל התמונה הראשונה בטשטוש. לאורחים שביקשו להפחית תנועה התמונות רק מתחלפות, בלי זום ובלי חלקיקים. בגלריית העיצובים הקטגוריה "מונפשים" (ותג "מונפשת" על הכרטיס) מרכזת את העיצובים שבנויים כהזמנה מונפשת, כל אחד סרט של חמש תמונות: למשל "שער השמיים" (שער בין העננים, עלייה אל מעל העננים וירידה אל המקום, ונפתח בחותם שעווה), "ירושלים של זהב", "הגן הקסום", "לילות פריז", "ליל הפנסים", "שביל האורות", "חוף השקיעה" ו"ערב גאלה". בחלקם יש חפץ שטס לאורך כל הגלילה ומגיע ליעד בסוף ההזמנה: כדורסל שנכנס לסל ("זריקה על הבאזר"), כדורגל שנכנס לחיבורים ("גול הזהב"), טיל שנוחת על הירח ("טיסה לירח"), כדור פורח שעולה אל הירח ("שמיים של שיר ערש"), ותפילין של ראש שעולות מתוך נרתיק הקטיפה ובסוף ההזמנה נחות על ראשו של חתן בר המצווה ("התפילין הראשונות": אחרי הטקסט האחרון יש מסך אחד בלי טקסט, שבו הילד מופיע והרצועות נכרכות). את התמונות אפשר להחליף בתמונות שלכם דרך כרטיס "תמונה או וידאו" של כל סקשן. הזמנה מונפשת (בעיצוב מונפש או בכל עיצוב שהופעל בו המתג) אפשר לערוך ולראות בתצוגה המקדימה בכל חבילה, אבל לפרסם רק בחבילות Pro ו־Business — בחבילה החינמית, בעיצוב שאינו פרימיום, כיבוי המתג מאפשר לפרסם כהזמנה רגילה (העיצובים המונפשים עצמם הם פרימיום).
- כשהעיצוב הקולנועי כבוי לאירוע הכרטיסים האלה לא מופיעים, ושינוי שמוסיף תמונה, פריסה, תנועה, צבעי סקשן או פתיחה לא נשמר ("העיצוב הקולנועי כבוי לאירוע הזה"); מה שכבר היה בטיוטה נשאר. לאורחים מוצגת אז ההזמנה הרגילה של העיצוב.
- המסך הראשי: רקע מהאפשרויות של העיצוב, או העלאת תמונה/סרטון משלכם (אחרי ההעלאה בוחרים "מה חשוב בתמונה" כדי שיישאר במסגרת), או "סרטון מיוטיוב או מ־Vimeo" — מדביקים קישור. קישור עם זמן (למשל youtu.be/xxxx?t=207 או "שיתוף" מדקה מסוימת ביוטיוב) מתחיל מאותו רגע ("מתחיל מ־3:27"). הסרטון מתנגן ברקע בלי סאונד ובלולאה; כתוביות כבויות כברירת מחדל ואפשר להפעיל ("הצגת כתוביות"). שכבת הכהיה עוזרת לקריאות הטקסט. אפשר גם "ברכה אישית עם שם המוזמן": מי שנכנס מהקישור האישי שלו רואה ברכה עם השם שלו ({guest} מוחלף בשם).
- עיצוב: פלטת צבעים — וגם "צבעים מתמונה": בוחרים תמונה מהמכשיר או מההזמנה ומקבלים שלוש הצעות (בהיר, ערב, גוון), כולן בניגודיות תקינה; התמונה לא עולה לשום מקום, ובעיצוב שמאפשר לשנות רק חלק מהצבעים משתנים רק הם — זוג גופנים (שני זוגות שמתאימים לעיצוב, "מומלץ להזמנה שלכם" — שלושה זוגות שמתאימים לסוג האירוע ולצבעים, בדוגמה חיה בשפות ההזמנה — ו"עוד גופנים" פותח ספרייה של זוגות גופנים עבריים ולועזיים שמתאימים לכל עיצוב), ומוזיקה — שיר מהספרייה של העיצוב, העלאת שיר משלכם, או הסאונד של סרטון הרקע. המוזיקה מתחילה רק אחרי שהאורח נוגע במסך (כך הדפדפנים עובדים), ויש לאורח כפתור להשתקה.
- "עיצוב אחר" (לשונית "עיצוב", למעלה): כל העיצובים של הגלריה לסוג האירוע, עם השמות והתאריך של ההזמנה; העיצוב הנוכחי מסומן. בוחרים עיצוב ומאשרים — השמות, התאריך, המקום, הטקסטים ואישורי ההגעה נשארים, והצבעים, הגופנים, התמונות של העיצוב והמוזיקה מתחלפים לשל העיצוב החדש (תמונה שהעליתם בעצמכם נשארת). ההזמנה כפי שהייתה נשמרת קודם בגרסאות, ו"ביטול" מחזיר אותה מיד. עיצוב פרימיום אפשר לבחור ולערוך בכל חבילה, ולפרסם ב־Pro וב־Business. כך מחליפים גם את העיצוב שנבחר אוטומטית באשף "אירוע חדש" כשלא בחרו בהזמנה דיגיטלית.
- שפות: הזמנה יכולה להיות בכמה משבע השפות (עברית, אנגלית, רוסית, ערבית, צרפתית, ספרדית, אמהרית). כל שדה מתמלא בכל שפה (לשונית לכל שפה ליד השדה; נקודה צהובה = חסר תרגום). בשפה שנוספה הטקסטים של העיצוב כבר כתובים בה, ואת השמות, המקום ושאר הפרטים כותבים (או מתרגמים). האורחים רואים את ההזמנה בשפת הדפדפן שלהם כשהיא אחת משפות ההזמנה, ועוברים בין השפות מתפריט השפות.
- תרגום אוטומטי (Pro ו-Business): בלשונית השפות, "תרגום ל…" ממלא את הטקסטים החסרים בשפה. שמות ומקומות לא מתורגמים לעולם (כותבים אותם בעצמכם), וגם המילים ב"מילים שלא מתרגמים". כל תרגום אוטומטי מחכה לבדיקה: "בדיקת התרגום" מציג את המקור ליד התרגום — מאשרים אחד אחד או הכל, או משנים (מה שכותבים בעצמכם נחשב מאושר). אם משנים אחר כך את המקור, התרגום חוזר לבדיקה. אי אפשר לפרסם כל עוד יש תרגום אוטומטי שלא אושר. בלי תרגום אוטומטי, אותו מסך משמש לתרגום ידני.
- אישור הגעה (בעורך): שם מלא או שם פרטי+משפחה, טלפון (אפשר לחייב), מייל (כבוי/רשות/חובה), מספר מבוגרים מקסימלי (עד 10) וילדים (אפשר לכבות), פרטים לכל אחד מהמגיעים, העדפות תזונה (עם הערה), שאלות משלכם — טקסט חופשי, בחירה מרשימה או כן/לא, וכל אחת יכולה להיות חובה — ברכה לזוג (אפשר לשנות את הכותרת או לכבות), וטקסטים משלכם לתודה, לתשובת "לא מגיעים" ולטופס שנסגר. התאריך האחרון לאישור נקבע בלשונית "הגדרות"; אחריו הטופס נסגר.
- לשונית "הגדרות" בעורך: פרטי האירוע (שמות, סוג האירוע, תאריך, שעות התחלה וסיום, אזור זמן, תאריך עברי — לפי היום, "ערב" או בלי, תצוגת שעות, ותאריך אחרון לאישור הגעה), השפות (הוספה או הסרה של שפה, הסדר שלהן בתפריט השפות שבהזמנה, השפה שנפתחת קודם, תרגום ובדיקת תרגום; באילו שפות מופיע התאריך העברי נבחר בפרטי האירוע), ו"קישור ושיתוף" — כתובת ההזמנה, כותרת ותיאור בשיתוף ותמונה בשיתוף (כולם ממולאים אוטומטית מפרטי ההזמנה — השמות, התאריך, המקום והתמונה הראשית — ומוצגים בתצוגה מקדימה של הקישור בוואטסאפ; אפשר לשנות כל אחד ולחזור לאוטומטי) ו"להסתיר ממנועי חיפוש" (מומלץ, מופעל כברירת מחדל).

## 4. פרסום ושיתוף
- "פרסום" בכותרת העורך: המערכת בודקת שחסר כלום (שגיאות חוסמות — למשל שם המקום — ואזהרות), ובוחרים כתובת (slug) להזמנה. אחרי הפרסום מקבלים קישור ${c.site}/i/<כתובת>.
- שינויים אחרי פרסום נשמרים כטיוטה; לוחצים "פרסום" שוב כדי שהאורחים יראו אותם — באותו קישור, בלי לשלוח מחדש.
- מסך השיתוף: הקישור (העתקה), הודעה מוכנה לוואטסאפ (בכל שפה), תצוגה של איך הקישור ייראה בוואטסאפ, וקוד QR להורדה (PNG/SVG). בווטסאפ תצוגת הקישור נשמרת אצלם בזיכרון, כך ששינוי תמונה עשוי להופיע רק בשיתוף חדש.
- ההזמנות לא מופיעות במנועי חיפוש (מוסתרות כברירת מחדל).
- Save the Date: הזמנה קצרה עם התאריך; אחר כך "יצירת ההזמנה המלאה" מהתפריט של הכרטיס, וה־Save the Date מקשר אוטומטית להזמנה המלאה כשהיא מתפרסמת.

## 5. רשימת מוזמנים (לשונית "מוזמנים ושליחה בוואטסאפ" של ההזמנה)
- העמוד הוא הרשימה עצמה. למעלה שורת סיכום באנשים (לא במשפחות): "N אנשים מגיעים מתוך M מוזמנים", כמה עוד מחכים לתשובה וכמה לא מגיעים. לידה שני כפתורים: "הוספת מוזמנים" (תפריט: "העלאת רשימה מאקסל" או "הוספה ידנית") ו"שליחה בוואטסאפ לכל המוזמנים" (מתחתיו כמה עוד לא קיבלו, המחיר והיתרה, או למה אי אפשר לשלוח עכשיו). בתפריט ⋯ שבראש העמוד: ייצוא לאקסל, קובץ לדוגמה, "עריכת הברכה האישית" (פותח את העורך) ושליחת השולחן לאורחים. ברשימה ריקה מוצג מדריך של שלושה צעדים.
- "העלאת רשימה מאקסל": קובץ xlsx או CSV (קובץ xls ישן — פותחים אותו באקסל, "שמירה בשם" כ־xlsx). המערכת מזהה לבד עמודות בעברית ובאנגלית: שם או שם מלא (או שם פרטי + שם משפחה), טלפון (עמודת נייד קודמת לאחרות), מייל, כמות מוזמנים, קבוצה ושפה (ארבעת האחרונים לא חובה; בעמודת השפה אפשר לכתוב "רוסית", "Русский", "العربية", English או קוד כמו ru) — גם בלי שורת כותרות. התצוגה המקדימה מראה שורות בעייתיות (אין שם, טלפון לא תקין, טלפון כפול) ומוזמנים עם מספר קווי (נכנסים לרשימה, אבל אי אפשר לשלוח אליהם בוואטסאפ). ייבוא חוזר של קובץ מעודכן לא מכפיל: מוזמן נמצא לפי הטלפון (או לפי השם כשאין טלפון) ומתעדכן. עד 5,000 שורות בקובץ. יש "קובץ לדוגמה" להורדה.
- "הוספה ידנית": מוזמן אחד. אם הטלפון כבר ברשימה, מוצג מי המוזמן שיש לו אותו. עריכה ומחיקה מהתפריט ⋯ של כל מוזמן.
- שפה לכל מוזמן (כשלהזמנה יש כמה שפות): בעמודת "שפה" ברשימה, בפרטי המוזמן, לכמה מסומנים יחד, או מהקובץ. הקישור האישי שלו נפתח בשפה הזו, ו"שליחה מהוואטסאפ שלי" כותבת לו בה. בלי שפה משלו — שפת ברירת המחדל של ההזמנה.
- קישור אישי לכל מוזמן: ההזמנה נפתחת עם הברכה והשם שלו, וטופס אישור ההגעה כבר ממולא בשם ובטלפון; התשובה שלו מקושרת אליו (גם כמה מוזמנים באותו מכשיר — כל אחד והתשובה שלו). מוזמן שענה דרך הקישור הכללי עם טלפון שנמצא ברשימה — מקושר אליו לבד.
- בטבלה שתי עמודות נפרדות: "הגעה" (מגיעים · כמה, "2 מתוך 3", לא מגיעים, או עוד לא ענו) ו"ההזמנה" (מצב השליחה: לא נשלח, בתור לשליחה, נשלח, נמסר, נקרא בוואטסאפ הרשמי, פתח/ה את ההזמנה, השליחה נכשלה עם הסיבה, ממתין לניסיון חוזר, ביקש/ה לא לקבל הודעות). מעל הטבלה חיפוש ושורת סינון — כל כפתור מראה כמה מוזמנים יש בו: כולם, לא נשלח, נשלח, פתחו, מגיעים, לא מגיעים, בלי תשובה, נכשלו, ו"ביקשו להוסיף".
- עדכון הגעה ידני (למשל אחרי שיחת טלפון): לוחצים על התא בעמודת "הגעה" ובוחרים מגיעים (וכמה — בברירת מחדל כמספר המוזמנים), לא מגיעים, או עוד לא ענו. תשובה כזו מסומנת "ידני", ונספרת בכל מקום: בסיכום, באישורי ההגעה, בסידור השולחנות וביום האירוע. יותר מגיעים ממספר המוזמנים מעדכן את מספר המוזמנים. תשובה שהמוזמן שלח בעצמו אפשר לשנות אבל לא לבטל. אי אפשר להוריד את "כמות מוזמנים" מתחת למספר שכבר אישרו (צריך קודם לעדכן את ההגעה).
- כמה מגיעים מקישור אישי: הטופס מאפשר עד מספר המוזמנים של אותו מוזמן (למשל הוזמנו 2 — אפשר לאשר 1 או 2) וכתוב בו "ההזמנה היא ל־2 אנשים". מי שרוצה להביא עוד אנשים מבקש זאת בטופס ("רוצים להגיע עם עוד אנשים?"); הבקשה מופיעה ברשימה כ"+N ביקשו" ובסינון "ביקשו להוסיף", ונספרים רק המוזמנים עד שהמארח לוחץ "לאשר" (מספר המוזמנים גדל וכולם נספרים ומקבלים מקום בסידור) או "לא לאשר". בקישור הכללי אין הגבלה כזו.
- מוזמן שעונה שוב (מהקישור האישי, או מהקישור הכללי עם הטלפון שלו) — התשובה החדשה מחליפה את הקודמת, ולא נספרת פעמיים.
- "שליחה מהוואטסאפ שלי": פותח את הוואטסאפ של המארח עם הודעה מוכנה והקישור האישי; המוזמן מסומן "נשלח ידנית". "סימון כנשלח" לשליחה בדרך אחרת.
- "ייצוא לאקסל": כל המוזמנים עם הסטטוס והקישור האישי.
- גבול מוזמנים להזמנה: חינם ${f.guestsPerInvitation}, Pro ${p.guestsPerInvitation}, Business ${b.guestsPerInvitation}.

## 6. שליחה בוואטסאפ מהמספר הרשמי
- "שליחה בוואטסאפ לכל המוזמנים" (או "שליחה בוואטסאפ" למסומנים): בוחרים למי (מי שעוד לא קיבל, המסומנים, או כולם), רואים את ההודעה בדיוק כפי שתיראה (טמפלט קבוע ומאושר של Meta: שלום <שם>, <המארחים> מזמינים אותך <לאירוע> ב<תאריך>, וכפתור "להזמנה ולאישור הגעה" עם הקישור האישי), כמה יישלחו בפועל ואת העלות.
- כל מוזמן מקבל את ההודעה בשפה שלו כשיש לה טמפלט מאושר (עברית ואנגלית תמיד; שפות נוספות לפי מה שאושר במערכת), ואחרת בשפת ההזמנה. החלון מראה כמה הודעות יישלחו בכל שפה ואת ההודעה בכל שפה. אמהרית: ל-וואטסאפ אין הודעות מאושרות באמהרית, אז ההודעה בשפת ההזמנה וההזמנה עצמה נפתחת באמהרית.
- לא נשלחים ולא משלמים עליהם: מוזמנים עם מספר קווי (בישראל רק נייד מקבל וואטסאפ), מי שביקש לא לקבל הודעות, ומי שכבר קיבל את ההזמנה (נשלחה, נמסרה, נקראה, נפתחה או שענה). שליחה חוזרת למי שכבר קיבל — רק כשמסמנים זאת במפורש ("לשלוח שוב גם למי שכבר קיבל"), והיא בתשלום.
- עלות: ₪${c.messagePrice} להודעה, כולל מע״מ — התעריף של וואטסאפ להודעת שיווק בישראל. כל הודעה = קרדיט אחד. הודעה שלא נמסרה (למשל מספר שלא רשום בוואטסאפ) מחזירה את הקרדיט, פעם אחת; הודעה שנמסרה לא מזוכה.
- וואטסאפ מבקש לפעמים להאט: ההודעות האלה נשלחות שוב לבד בעוד דקה ואחר כך בעוד חמש דקות (אפשר לסגור את הדף); אחרי 3 ניסיונות הודעה נכשלת והקרדיט חוזר. הודעה שאולי כבר הגיעה לוואטסאפ לא נשלחת פעמיים — היא מסומנת כנכשלה, הקרדיט חוזר, ואפשר לשלוח שוב.
- מוזמן שמשיב להודעה "הסר" או STOP (או מפסיק לקבל הודעות שיווק) לא מקבל יותר הודעות מהמספר הזה, מאף מארח.
- צריך לאשר שהמוזמנים מכירים את המארח ומצפים להזמנה (מדיניות של וואטסאפ).
- ההזמנה צריכה להיות מפורסמת לפני השליחה. אם השליחה הרשמית עוד לא חוברה במערכת — משתמשים ב"שליחה מהוואטסאפ שלי".
- קרדיטים: Pro מקבלת ${p.monthlyCredits} בחודש, Business ${b.monthlyCredits} בחודש; קונים עוד ב"חבילה וחיובים": ${packs}. קרדיטים לא פגים.

## 7. אישורי הגעה (לשונית "אישורי הגעה")
- לוח עם מגיעים (מבוגרים/ילדים), תשובות, לא מגיעים, וזמן עד הדדליין; גרפים של העדפות תזונה ותשובות לשאלות; טבלה עם חיפוש וסינון (מגיעים/לא, עם הודעה, עם העדפות תזונה) — הסינונים הפעילים מופיעים כתגיות שאפשר להסיר, עם "מוצגות X מתוך Y". בטלפון כל תשובה היא כרטיס. לחיצה על שורה או כרטיס פותחת את הפרטים (כולל מחיקה).
- ייצוא לאקסל (פועל מהתשובה הראשונה). התראות במייל: על כל תשובה, סיכום יומי (בבוקר), או כבויות.
- אורח שכבר ענה רואה "כבר עניתם" ויכול לערוך את התשובה מאותו מכשיר; התשובה מתעדכנת במקום (לא נכפלת).

## 8. חבילות ותשלומים ("חבילה וחיובים", /app/billing)
- חינם: ${f.activeInvitations} הזמנה פעילה, עד ${f.guestsPerInvitation} מוזמנים, העיצובים הבסיסיים, שליחה מהוואטסאפ של המארח.
- Pro: ₪${c.prices.pro} לחודש — עד ${p.activeInvitations} הזמנות פעילות, עד ${p.guestsPerInvitation} מוזמנים, כל העיצובים כולל פרימיום, בלי "נוצר ב־${c.brand}", ${p.monthlyCredits} הודעות וואטסאפ בחודש.
- Business: ₪${c.prices.business} לחודש — הזמנות ללא הגבלה, עד ${b.guestsPerInvitation} מוזמנים, ${b.monthlyCredits} הודעות בחודש, תמיכה בעדיפות.
- המחירים כוללים מע״מ. התשלום בעמוד מאובטח של PayPlus (אשראי, Bit, Apple Pay, Google Pay), והחשבונית נשלחת במייל. החבילה מתחדשת כל חודש עד ביטול.
- ב"חבילה וחיובים" רואים את החבילה, הניצול (הזמנות, קרדיטים) והיסטוריית התשלומים — רכישות, חידושים חודשיים ותנועות קרדיטים. תשלום שעוד בבדיקה מוצג כ"ממתין" ומתעדכן לבד.
- ביטול: "ביטול המנוי" בחבילה וחיובים — אין חיובים נוספים, והחבילה נשארת עד סוף התקופה ששולמה. אפשר גם לבטל רכישה תוך 14 יום לפי חוק הגנת הצרכן (בניכוי 5% או ₪100, הנמוך מביניהם, ובניכוי מה שכבר נוצל). הודעות שכבר נשלחו לא מוחזרות.
- חיוב חודשי שנכשל: החבילה נשארת עוד 14 יום. "תשלום מחדש" בחבילה וחיובים משלם שוב על החבילה (אפשר בכרטיס אחר) ומחליף את החיוב שנכשל.

## 9. החשבון ("החשבון שלי", /app/account)
- חשבון שנפתח דרך Badook Events (מערכת האירועים): נכנסים בקישור שמגיע משם — הוא פותח את "כניסה ל־Badook", ולוחצים "המשך ל־Badook" (כל קישור עובד פעם אחת). אפשר גם להיכנס עם Google באותו מייל, או "שכחתי סיסמה" כדי לקבוע סיסמה — ומאז נכנסים כרגיל, בלי קישורים מ־Badook Events. ב"החשבון שלי" רשום "כניסה: Badook Events". Badook Events יכולה לתת לחשבון כזה הנחה באחוזים על החבילות (Pro ו־Business): היא מופיעה ב"חבילה וחיובים" ("הנחה של …% על החבילות · בזכות Badook Events", ועד מתי אפשר לקנות בה), והמחירים שם כבר אחרי ההנחה. חבילה שנקנתה בהנחה ממשיכה להתחדש כל חודש באותו מחיר עד שמבטלים או מחליפים אותה, גם אחרי שההנחה הסתיימה. קרדיטים לוואטסאפ לא בהנחה (הם במחיר העלות של Meta). את ההנחה נותנת Badook Events, לא אנחנו: מי שמבקש הנחה פונה אליהם.
- עדכון שם וטלפון, שינוי סיסמה, ומחיקת החשבון (מוחקת לצמיתות את כל ההזמנות, המוזמנים, התשובות והקבצים, ומפסיקה את המנוי — הזמנות שפורסמו מפסיקות לעבוד). אם את החיוב החודשי לא הצלחנו לעצור אוטומטית, הצוות מקבל התראה ועוצר אותו ידנית.

## 10. נגישות, פרטיות ועוגיות
- כפתור הנגישות (הכפתור העגול שצף בצד שמאל של כל עמוד באתר ובמערכת): הגדלת טקסט, ניגודיות גבוהה, הדגשת קישורים, גופן קריא, ריווח שורות, עצירת אנימציות וסמן גדול. הצהרת הנגישות: /accessibility.
- מדיניות פרטיות: /privacy. תנאי שימוש: /terms. מדיניות עוגיות: /cookies. בעמודי האתר, סרטונים מ־YouTube (במצב הפרטיות המוגברת שלו) ומפות Google נטענים כברירת מחדל; "רק חיוניות" בהודעת העוגיות, או "הגדרות עוגיות" בתחתית עמודי האתר, מכבים אותם.
- בכל הזמנה, בתחתית, יש קישורים להצהרת הנגישות ולמדיניות הפרטיות.
- בכל הזמנה שיש בה תנועה, לאורחים יש כפתור "עצירת האנימציות" (הכפתור העגול בפינה התחתונה, מול כפתור המוזיקה): הוא עוצר את סרטון הרקע, החלקיקים והלולאות של האיורים, ולחיצה נוספת מחזירה אותם. לאורחים שביקשו במכשיר פחות תנועה ההזמנה ממילא שקטה, והכפתור לא מופיע.
- המידע נשמר בשרתים באיחוד האירופי, לא נמכר, ומארחים יכולים למחוק מוזמנים ותשובות בכל רגע.
- שאלות לעוזר נשלחות לספק הבינה המלאכותית (Anthropic) רק כדי לענות עליהן, בלי שם, מייל או פרטי חשבון, ולא נשמרות אצלנו. לכן לא כותבים בצ׳אט סיסמאות, פרטי אשראי או מידע אישי של מוזמנים.
- תרגום אוטומטי: כשמבקשים אותו, הטקסטים של ההזמנה (בשפה שבה נכתבו) נשלחים לספק הבינה המלאכותית (Anthropic), שמחזיר אותם מתורגמים. שמות שבטקסטים נשארים כמו שהם, ושום דבר על המוזמנים לא נשלח. התרגומים נשמרים עם ההזמנה; הרישום של כל הפעלת תרגום (בשביל המגבלה היומית) נמחק אחרי יומיים. פרטים ב־/privacy.

## 11. בעיות נפוצות
- סרטון הרקע לא מתנגן: חלק מהטלפונים (למשל במצב חיסכון בסוללה) עוצרים ניגון אוטומטי עד שנוגעים במסך; מי שביקש "תנועה מופחתת" רואה תמונה במקום סרטון. בסרטון מיוטיוב ודאו שהסרטון ציבורי ומאפשר הטמעה.
- המוזיקה לא מתחילה: היא מתחילה רק אחרי לחיצה של האורח (מדיניות הדפדפנים).
- האורחים לא רואים שינוי: צריך ללחוץ "פרסום" שוב אחרי עריכה.
- הודעת וואטסאפ נכשלה: בדרך כלל המספר לא רשום בוואטסאפ, קווי או לא תקין; הקרדיט הוחזר. "ממתין לניסיון חוזר" — וואטסאפ ביקש להאט, וההודעה תישלח לבד בעוד כמה דקות.
- ייבוא האקסל לא מזהה עמודות: ודאו שורת כותרות כמו "שם" ו"טלפון", או הורידו את "קובץ לדוגמה". קובץ xls ישן — שומרים אותו באקסל כ־xlsx.
- לא מצליחים להתחבר: "שכחתי סיסמה" בעמוד הכניסה; אם נרשמתם עם Google — היכנסו עם Google.

## 12. יצירת קשר עם אדם
- הדרך המומלצת: פנייה לצוות ב"תמיכה" (/app/support) — ראו סעיף 24. מהצ׳אט הזה: "לדבר עם נציג" בתחתית הצ׳אט פותח פנייה עם השיחה.
- טופס יצירת קשר: ${c.site}/contact (נושאים: תמיכה, חיובים, פרטיות, נגישות, שיתופי פעולה).${c.supportEmail ? ` מייל: ${c.supportEmail}.` : ''}
- לנושאים שדורשים גישה לחשבון (החזר כספי, בעיה בחיוב מסוים, בקשת מידע לפי חוק הפרטיות) — לפתוח פנייה ב"תמיכה", או לפנות בטופס.

## 13. סידור שולחנות (לשונית "סידור שולחנות" של ההזמנה)
- במסך ההזמנה, לשונית "סידור שולחנות": מפת האולם ולידה רשימת האורחים (בטלפון: "מפה | אורחים", ו"מסך מלא"). כלול בכל החבילות; "סידור אוטומטי" כלול בחבילת Premium (תוכנית Pro) ומעלה. הכל נשמר לבד, ושינויים משני חלונות מתמזגים.
- התחלה בלי תמונה של האולם: כשהמפה ריקה מופיעים "אולמות מוכנים" — אולם קלאסי, אולם רחב, גן אירועים ושולחנות אבירים — עם במה, רחבה, בר, כניסה ושולחנות לפי מספר מאשרי ההגעה (או המוזמנים); בחירה מציירת את האולם ואת השולחנות, ואחר כך מזיזים ומשנים הכול (ו"ביטול" מחזיר). אפשר גם "להתחיל מאולם ריק", ולבחור אולם מוכן גם מחלון "תוכנית האולם". בלי תמונה המפה מציירת רצפה וקירות של אולם 30×20 מטר. בכניסה הראשונה מופיע מעל המפה כרטיס "פעם ראשונה בסידור שולחנות?" עם הסרטון, ואחר כך הוא תמיד זמין ב"סרטון הדרכה (45 שנ׳)" בראש המסך: סרטון של 45 שניות עם קריינות וכתוביות (אולם, שולחנות, משפחות, סידור אוטומטי עם כללים במילים, הדפסה ושליחה, ומפת האולם בלייב ביום האירוע), שלושה טיפים וקישור למדריך.
- תמונת האולם (הכפתור "תמונת האולם" בסרגל המפה): כדאי לבקש מהאולם תמונה או PDF של מפת האולם. תמונה (PNG, JPG, WebP) או PDF (העמוד הראשון), עד 15MB. כיול קנה המידה: "ציור קו לכיול" (קו לאורך משהו שאורכו ידוע, ואז האורך במטרים) או רוחב התוכנית כולה במטרים; בלי כיול מניחים אולם ברוחב 30 מטר. אולם שעובד עם Badook Events יכול לשלוח את התוכנית מראש, ואז היא כבר מופיעה ("שימוש בתוכנית של האולם"); אפשר להחליף אותה.
- שולחנות: "שולחן" מוסיף עגול (10 מקומות), מרובע (ריבוע אמיתי, 8 מקומות — שניים בכל צד), מלבני (8, לאורך הצדדים) או אבירים (20) עם המספר הפנוי הבא; לחיצה על שולחן פותחת את חלון השולחן: מספר, שם, צורה, מקומות, גודל (צלע לריבוע; רוחב ועומק למלבני ולאבירים), סיבוב, מה יש לידו (במה, רחבה, יציאה, נגיש לכיסא גלגלים), "נעילת שולחן", שכפול ומחיקה. גוררים כדי להזיז (הצמדה לרשת כל חצי מטר), גלגלת או שתי אצבעות להגדלה, ביטול/חזרה. במקלדת: Tab לשולחן, חצים להזזה, R לסיבוב, Delete למחיקה, Enter להושבה. "סימון" מסמן במה, רחבת ריקודים, בר, מזנון, כניסה ויציאה.
- הושבה: ברשימה מופיע מי שאישר הגעה, וכל משפחה (הזמנה אחת) יושבת תמיד יחד. גוררים משפחה לשולחן במפה, או "הושבה" ובוחרים שולחן; שולחן בלי מספיק מקומות פנויים חוסם עם הודעה כמה נשארו. אפשר להציג גם מי שעוד לא ענו (לפי הכמות ברשימת המוזמנים). "הגדרות ובקשות" של משפחה: קטגוריה (בברירת מחדל הקבוצה מהרשימה), קרוב/רחוק מהבמה, מהרחבה ומהיציאה, כיסא גלגלים (רק בשולחן נגיש), וכללים: "חייבים לשבת יחד עם" / "לא לשבת עם", חובה או עדיף.
- סידור אוטומטי: למעלה "ספרו במילים מי עם מי" — כותבים חופשי ("סבתא ליד הבמה, החברים מהצבא ביחד, דוד משה לא באותו שולחן עם דודה רחל"), "להבין את הכללים" מציג רשימה לסימון (ביחד / לא באותו שולחן, חובה או בקשה; ליד או רחוק מהבמה, מהרחבה או מהיציאה; שולחן נגיש) ומה שלא הובן, ו"להוסיף" מוסיף רק את מה שסימנו (אפשר לבטל). זמין כשיש בינה מלאכותית באתר, עם מכסה יומית; רשימת המוזמנים משמשת רק כדי להבין למי התכוונו. אחר כך בוחרים אם כל קטגוריה ביחד, לערבב או לא משנה, כמה מלא לפחות כל שולחן, ואם להושיב גם מי שעוד לא ענו, ולוחצים "סידור". הסידור עובד כמו מארגן מקצועי: משפחה תמיד יחד, שולחן לא מתמלא מעבר למקומות, כללי חובה קודם, ועם "כל קטגוריה ביחד" — אף אחד לא נשאר היחיד מהקבוצה שלו בשולחן כשאפשר להושיב אותו עם מישהו מהקבוצה. מתקבלים סיכום ("כל משפחה יושבת יחד · כל 3 הכללים נשמרו"), ציון (0 = מושלם; נקודות קנס על מה שלא הסתדר) ורשימה במילים של מה שלא הסתדר. שולחן שאוהבים נועלים ("נעילת שולחן"), ו"סדר מחדש" מסדר את השאר מחדש. "ביטול" מחזיר את הסידור הקודם.
- משפחה שהגדילה את אישור ההגעה אחרי שהושבה עלולה למלא שולחן מעבר למקומות: מופיעה התראה, ומזיזים מישהו או מוסיפים מקומות. מי שהודיע שלא יגיע אחרי שהושב: "לפנות את המקומות".
- "הדפסה": מפה, רשימת האורחים לפי א״ב עם מספר השולחן (לכניסה לאולם) ורשימה לפי שולחנות, בדף A4 או A3, לאורך או לרוחב; "הדפסה / שמירה כ־PDF". "Excel": קובץ עם כל האורחים ומספרי השולחנות, וגיליון לפי שולחנות.

## 14. גלריה חיה (לשונית "גלריה" של ההזמנה)
- האורחים מעלים תמונות וסרטונים מהאירוע ישר מהטלפון, בלי הרשמה ובלי אפליקציה, והם מופיעים אצל כולם בזמן אמת. כלולה ב־Pro וב־Business; בחבילה החינמית הלשונית מציעה שדרוג. "הפעלת הגלריה" יוצרת קישור להעלאה וקוד QR (להורדה כ־PNG או SVG, להדפסה על השולחנות) ששולחים לאורחים. "קישור חדש" מבטל את הקודם מיד, גם את הקוד שכבר הודפס.
- הגדרות: פרסום "מופיעה מיד" (מה שנראה מטושטש, חשוך או לא מתאים מחכה לאישור) או "אחרי אישור שלכם" (הכל מחכה); "השהיית העלאות" (הגלריה נשארת גלויה); "קוד כניסה" שהאורחים מקלידים (3–32 תווים, נשמר מוצפן ולא מוצג שוב — אפשר רק להחליף או להסיר); "זמני העלאה" (לפני ואחרי אפשר רק לצפות); וכיבוי הגלריה כולה.
- "ממתינים לאישור": אישור מכניס לגלריה; דחייה או הסתרה משאירות בחוץ (אפשר להחזיר); מחיקה מוחקת לצמיתות, גם את קובץ המקור. בדיקה אוטומטית של התוכן (אם החבילה כוללת אותה) עוצרת לאישור מה שנראה לא מתאים, וחוסמת מה שבוודאות לא מתאים.
- האורח: פותח את הקישור, בוחר כמה תמונות וסרטונים, ורואה "3 מתוך 7 הועלו". הטלפון מקטין את התמונות לפני השליחה (קובץ המקור נשמר בנפרד), וההעלאה ממשיכה לבד כשהקליטה חוזרת — גם אחרי סגירה ופתיחה של העמוד. אורח יכול למחוק מה שהעלה מאותו טלפון. סרטון עד 200MB וחמש דקות, תמונה עד 40MB.
- העמוד של האורחים בנוי כמו אינסטגרם של האירוע: למעלה "סטוריז מהאירוע" — עיגול לכל מי ששיתף סטורי ("הסטורי שלך" מוסיף), לחיצה מנגנת במסך מלא; מתחת שורת שיתוף ("שתפו רגע מהאירוע…"); ואז הפיד — פוסטים עם שם, זמן, התמונות (כמה תמונות שנבחרו יחד הן פוסט אחד שמחליקים בו, עם נקודות ו"2/5") ולב. בשיתוף בוחרים "סטורי" (בעיגולים למעלה) או "פוסט בפיד" (נשאר בפיד ואפשר לעשות לו לייק), כותבים שם (לא חובה) ובוחרים מהגלריה של הטלפון או מצלמים. לייק: לחיצה על הלב או הקשה כפולה על התמונה; לייק אחד לכל טלפון ופוסט, אפשר לבטל, והמספר מתעדכן אצל כולם בזמן אמת. "כל התמונות" מציג את כל התמונות והסרטונים (גם של הסטוריז) ברשת. הכול נשמר אצל המארחים — הורדה, מסך באולם וסרט הרגעים — בלי קשר לאן שותף. בצד העמוד כפתור נגישות (גודל טקסט, ניגודיות, עצירת אנימציות ועוד) בשפת העמוד.
- "מסך באולם" (Business): קישור נפרד שפותחים במחשב שמחובר למקרן או לטלוויזיה — התמונות מתחלפות לבד, וחדשות נכנסות תוך שניות. רק מה שפורסם מופיע.
- "הורדת הכל (ZIP)": כל קובצי המקור בקובץ ZIP (בגלריה גדולה כמה קבצים של עד 500MB), עם תאריך ושעה בשם כל קובץ. "מחיקת הגלריה" מוחקת הכל לצמיתות.
- "שליחת הקישור לאורחים" (בכרטיס הקישור): שולח לכל אורח ברשימה את הקישור לגלריה עם הקישור האישי שלו — מהמספר הרשמי בוואטסאפ (קרדיט אחד למשפחה, ורק אחרי ש־WhatsApp אישרה את תבנית ההודעה השלישית), או "שליחה מהוואטסאפ שלי" ליד כל משפחה, או "העתקת ההודעה עם הקישור" (לשליחה בכל דרך אחרת). כל אורח מקבל את ההודעה בשפה שלו (מהמספר הרשמי — כשהתבנית אושרה בשפה הזו, אחרת בשפת ההזמנה), והקישור פותח לו את הגלריה בשפה שלו; החלון מראה כמה הודעות יישלחו בכל שפה ואת ההודעה בכל שפה. מצבי השליחה (נשלח, נמסר, נקרא) כמו בהזמנות, והודעה שנכשלה מחזירה את הקרדיט.
- פרטיות: הקבצים באחסון פרטי, והקישורים אליהם פגים אחרי כמה שעות. הגלריה עצמה לא מזהה פנים — זיהוי פנים יש רק ב"התמונות שאני בהן" (סעיף 17), כשהמארחים מפעילים אותו. פרטים ב־/privacy.
- תקלות: אורח רואה "הקישור לא עובד" — הקישור הוחלף בחדש (שלחו את העדכני). "המארחים השהו את ההעלאה" או "ההעלאה לגלריה הסתיימה" — בדקו את ההשהיה ואת זמני ההעלאה בהגדרות. תמונה שלא מופיעה בגלריה כנראה ממתינה לאישור (אצל האורח רשום "ממתין לאישור המארחים").

## 15. יום האירוע: מספר השולחן לאורחים, רישום בכניסה ומפת אולם חיה (לשונית "יום האירוע" של ההזמנה)
- מה כלול: "מדריך השולחן" לאורח ושליחת מספרי השולחנות — בחבילת Premium (תוכנית Pro) ומעלה; רישום בכניסה, מפת האולם החיה והושבה מחדש תוך כדי האירוע — בחבילת VIP (תוכנית Business). בלי החבילה הלשונית מציעה שדרוג.
- מדריך השולחן של האורח: עמוד אישי (מהקישור שבהודעה, /e/<כתובת ההזמנה>/table) עם "השולחן שלך: 12", מפת האולם (בלי שמות של אורחים אחרים), והדרך מהכניסה לשולחן — מסביב לשולחנות. "לסובב את המפה עם הטלפון" מסובב את המפה לפי הכיוון שהטלפון מסתכל (באייפון צריך לאשר גישה לחיישני התנועה). העמוד עובד גם בלי קליטה אחרי שנפתח פעם אחת (נשמר לערב). כשיש רישום בכניסה, יש בו גם קוד QR אישי לכניסה. אורח שעוד לא הושב רואה "השולחן שלך יופיע כאן". המדריך נפתח בשפה של האורח (השפה שלו ברשימת המוזמנים, אחרת שפת ההזמנה), ואפשר לעבור בו לכל שפה של ההזמנה; גם ההודעה עם מספר השולחן נשלחת בשפה של האורח (בוואטסאפ מהמספר הרשמי — אם התבנית אושרה בשפה הזו, אחרת בשפת ההזמנה). עמדת הכניסה וכרטיסי השולחן להדפסה בעברית או באנגלית.
- שליחת מספר השולחן: "לשלוח לאורחים את השולחן" — בלשונית "סידור שולחנות", ב"עוד" שבלשונית המוזמנים, ובלשונית "יום האירוע". לכל משפחה: מספר השולחן וקישור אישי למפה. שליחה מהמספר הרשמי בוואטסאפ (קרדיט אחד למשפחה) — רק אחרי ש־WhatsApp אישרה את תבנית ההודעה השנייה; עד אז, ובכל מקרה: "שליחה מהוואטסאפ שלי" ליד כל משפחה (הודעה מוכנה, והמשפחה מסומנת כמי שקיבלה), "סימון שקיבלו" (אמרתם בעצמכם), "העתקת הקישור למפה", ו"כרטיסי שולחן להדפסה" (כרטיס לכל משפחה, לפי א״ב או לפי שולחנות, ועם קוד כניסה כשיש רישום בכניסה).
- הנעילה: אחרי שמשפחה קיבלה את מספר השולחן, הזזה שלה (או שינוי מספר השולחן שלה) מבקשת אישור, ורק היא מקבלת עדכון — בוואטסאפ מהמספר הרשמי אם מסמנים, או מהוואטסאפ שלכם (היא מופיעה בלשונית "צריכים עדכון"). כל שינוי כזה נשמר ב"היסטוריה" (בכפתור "היסטוריה" בסידור השולחנות), ואפשר לבטל שינויים אחרונים.
- עמדת הכניסה: בלשונית "יום האירוע" — כרטיס "עמדת הכניסה" עם קישור (העתקה, פתיחה, קוד QR להורדה). פותחים אותו בטלפון או בטאבלט שבכניסה, בלי להתחבר; כמה עמדות יכולות להשתמש באותו קישור. בעמדה: "סריקה" (מצלמה; צריך לאשר גישה למצלמה) של הקוד שבטלפון של האורח או על כרטיס השולחן, או חיפוש לפי שם או הספרות האחרונות של הטלפון. בוחרים כמה הגיעו (אפשר חלק מהמשפחה, והשאר אחר כך), ורואים מיד את מספר השולחן. "ביטול" מבטל רישום שנעשה בטעות. "קישור חדש" מבטל את הקודם מיד.
- מפת האולם החיה (לשונית "יום האירוע"): כמה אנשים ומשפחות הגיעו מתוך מי שאישר, שולחנות שהתמלאו, וההגעה האחרונה; "מפה" — כל שולחן צבוע לפי כמה מהאנשים שלו הגיעו (ירוק כהה יותר = מלא יותר, אדום = יותר אנשים ממקומות); "שולחנות" — רשימה עם חיפוש משפחה; "הגעות" — גרף לפי 5 דקות. "הגיעו לאחרונה" עם ביטול. מתעדכן לבד מכל העמדות. 45 דקות אחרי תחילת האירוע: התראה על שולחנות שפחות מחצי מהאנשים שלהם הגיעו, והצעות לאיחוד שני שולחנות חצי ריקים.
- הושבה מחדש תוך כדי האירוע: לחיצה על שולחן פותחת את המשפחות שבו — "הגיעו" (רישום מהטלפון שלכם), "העברה" לשולחן אחר, או "איחוד לשולחן אחר". אפשר לכתוב למה, ולסמן לשלוח למשפחה את השולחן החדש. שולחן בלי מקום חוסם, אלא אם בוחרים "להעביר בכל זאת (מוסיפים כיסאות)". כל שינוי נשמר בהיסטוריה עם ביטול (אם המשפחות לא הוזזו שוב מאז).
- פרטיות: רישום בכניסה שומר איזו משפחה הגיעה, כמה אנשים, מתי ובאיזו עמדה — ונמחק 30 יום אחרי האירוע; רישום שבוטל נמחק אחרי יום. פרטים ב־/privacy.
- תקלות: "הקישור לא עובד" בעמדה — נוצר קישור חדש (שלחו לעמדות את העדכני). המצלמה לא נפתחת — אשרו גישה למצלמה בהגדרות הדפדפן, או חפשו לפי שם. "הקוד לא מוכר" — הקוד של הזמנה אחרת, או שהאורח לא ברשימת המוזמנים (חפשו לפי שם). המפה של האורח לא מסתובבת — הטלפון בלי מצפן או שלא אושרה הגישה (המפה עובדת גם בלי).

## 16. עצבו לי: שלושה עיצובים מהתמונות שלכם
- איפה: בעורך — לשונית "עיצוב" ← "עצבו לי"; ובגלריית העיצובים (הזמנה חדשה) — הכרטיס "עצבו לי מהתמונות" למעלה. כלול בחבילת VIP (תוכנית Business); בלי החבילה מופיעה הצעה לשדרג.
- בוחרים 3–5 תמונות: מהתמונות שכבר בהזמנה (לחיצה מוסיפה ולחיצה נוספת מסירה) או "העלאת תמונות" מהמכשיר. התמונה הראשונה היא תמונת הפתיחה; הכוכב על תמונה אחרת מעביר אותה למקום הראשון. אפשר לכתוב "מצב רוח" בכמה מילים (למשל: ים, שקיעה, זהב עדין) — לא חובה.
- "הציגו לי 3 עיצובים": מתקבלים שלושה עיצובים שלמים ושונים — תבנית, צבעים (תמיד קריאים), גופנים, פתיחה, איפה כל תמונה בהזמנה ובאיזו פריסה, כמה תנועה, ומשפט פתיחה וסיום בשפות ההזמנה — עם משפט שמסביר למה. כל עיצוב מוצג בתצוגה חיה: במחשב זה לצד זה, בטלפון מחליקים או לוחצים "העיצוב הבא". "עוד שלושה עיצובים" מציג עיצובים אחרים מאותן תמונות.
- "בוחרים בעיצוב הזה": בעורך — מחליף את העיצוב בצעד אחד; הטקסטים והפרטים נשארים, מה שהיה נשמר קודם ב"גרסאות", ו"ביטול" מחזיר. בגלריה — נוצרת הזמנה חדשה על העיצוב שנבחר, התמונות עולות אליה והעורך נפתח.
- בלי בינה מלאכותית (אם היא לא זמינה, לא ענתה, או אחרי המכסה היומית — 12 בקשות ביום לחשבון) העיצובים מורכבים אוטומטית מהצבעים של התמונות, והמסך אומר זאת.
- פרטיות: התמונות מוקטנות במכשיר ונשלחות רק כדי להציע את העיצובים, בלי שמות; לא נשמר כלום מהבקשה. רק תמונות שעיצוב שבחרתם משתמש בהן עולות להזמנה.

## 17. עיון המשפחה: קישור לטיוטה עם הערות
- איפה: בעורך, הכפתור "הערות" בסרגל העליון (בטלפון: בתפריט ⋯). כלול בכל החבילות.
- "יצירת קישור לעיון" (אפשר לבחור תוקף: בלי תפוגה, 7 או 30 יום) ← "העתקת הקישור", "פתיחה" או "שליחה בוואטסאפ". הקישור מראה את הטיוטה כמו שהיא עכשיו ומתעדכן לבד כשאתם עורכים, עם סימן "טיוטה". לא שולחים ממנו אישורי הגעה ואף אחד לא נספר; מנועי חיפוש לא מציגים אותו.
- בני המשפחה (בלי חשבון): "הוספת הערה" ← לוחצים על המקום בהזמנה (או בוחרים חלק מהרשימה בטופס) ← כותבים שם (פעם אחת; נשמר רק בדפדפן שלהם) והערה. ההערות מופיעות כמספרים על ההזמנה וברשימה "הערות"; אפשר לענות על הערה ולמחוק הערה שכתבתם.
- אצלכם: ההערות מגיעות בזמן אמת — מספר על הכפתור "הערות", מספר אדום ליד כל סקשן ברשימה, ומספרים על התצוגה המקדימה (לחיצה על מספר פותחת את ההערה). בחלון "הערות": סינון פתוחות / טופלו / הכל, "תשובה" (מופיעה למשפחה מיד), "סימון כטופלה" / "פתיחה מחדש", "הצגה בתצוגה" ו"מחיקה".
- הקישור: "קישור חדש" מחליף אותו (הקודם מפסיק לעבוד מיד), "ביטול הקישור" מפסיק אותו; ההערות נשמרות בשני המקרים. תוקף שפג — בוחרים תוקף חדש והקישור חוזר לעבוד.
- "עדכונים במייל": על כל הערה (לכל היותר מייל אחד ב־10 דקות), סיכום יומי, או בלי מיילים.
- תקלות: "הקישור לא זמין" אצל המשפחה — הוא הוחלף, בוטל או שהפיצ׳ר כובה (שלחו את הקישור העדכני). "פג תוקף הקישור" — בחרו תוקף חדש. ההערות נמחקות 90 יום אחרי האירוע.

## 18. גרסאות ושמירות
- איפה: בעורך, "גרסאות" (סמל השעון) בסרגל העליון (בטלפון: בתפריט ⋯).
- מה יש שם: כל פרסום ("גרסה 3 · פורסמה", והגרסה שבאוויר מסומנת "באוויר"), ושמירות של הטיוטה — אוטומטית תוך כדי עבודה (לכל היותר פעם ב־10 דקות), "לפני שחזור" ו"לפני עיצוב חדש". סינון: הכל / פורסמו / שמירות.
- לכל אחת: "מה ישתנה בשחזור" — רשימה במילים של מה יהיה שונה בטיוטה, סקשן אחרי סקשן; "צפייה" — פותח בלשונית חדשה בלי לשנות כלום; "שחזור" — מחליף את הטיוטה (מה שהיה נשמר קודם, ואפשר גם "ביטול" מיד). האורחים לא רואים כלום עד שמפרסמים שוב.
- שמירות נשמרות 90 יום (עד 60 להזמנה); גרסאות שפורסמו נשמרות תמיד.

## 19. הקראת ההזמנה וכתוביות לסרטונים
- הקראה: באורחים — כפתור "האזנה להזמנה" (אוזניות) מעל כפתור המוזיקה; קול קורא את השמות, התאריך, המקומות והטקסטים, בשפה שמוצגת. כשההקראה מתחילה המוזיקה נעצרת, ו"עצירת ההקראה" עוצר. כלול בחבילת Premium (תוכנית Pro) ומעלה.
- ההקראה מוכנה פעם אחת בכל פרסום שבו הטקסט השתנה (כמה דקות אחרי הפרסום, ברקע — הפרסום לא מחכה לה). עד שהיא מוכנה, או אם לא הצליחה, הטלפון של האורח מקריא בעצמו כשיש בו קול לשפה; אם אין — הכפתור לא מופיע.
- אצלכם: הגדרות ← "קישור ושיתוף" ← "הקראת ההזמנה": המתג "להציע לאורחים להאזין" (כיבוי מסיר את הכפתור מההזמנה), ומצב כל שפה: "מוכנה", "בהכנה…", "תתעדכן בפרסום הבא" או "הטלפון של האורח מקריא".
- כתוביות: בסרטון שהעליתם (במסך הראשי או בסקשן) — "כתוביות": לכל שפה "העלאת קובץ" (‎.vtt או ‎.srt; ‎.srt מומר לבד), "הקלדה" (שורה לכל כתובית: התחלה, סיום וטקסט, זמנים כמו 0:03 או 1:05.5) או "הסרה". האורחים רואים את הכתוביות בשפה שמוצגת. סמנו "מדברים בסרטון" — ואז לפני הפרסום תופיע תזכורת לשפה שחסרות לה כתוביות.

## 20. סרט הרגעים (לשונית "גלריה" ← "יצירת סרט")
- מה זה: סרט קצר מהתמונות והסרטונים שבגלריה, ערוך לפי הקצב של השיר — נוצר כולו בדפדפן של המארח, בלי לשלוח תמונות לשרת. כלול בחבילת VIP (תוכנית Business); בלי החבילה הכרטיס מציע שדרוג.
- הבחירה: הסרט בוחר לבד את הצילומים הטובים — חדים, מוארים, עם אנשים, מכל שלבי האירוע, בלי כפילויות — ומשלב תמונות עם קטעים קצרים מסרטונים. "נעיצה" מכניסה צילום תמיד, ה־X מוציא אותו, החיצים משנים את הסדר, ו"הוספת צילומים" מציגה את כל הגלריה. "איפוס הבחירה" מבטל הכל. הבחירה נשמרת בדפדפן הזה.
- הגדרות: אורך 30, 60 או 90 שניות (בערך — הסרט מסתיים בסוף המשפט המוזיקלי הקרוב); "לאורך" (לטלפון) או "לרוחב" (למסך); 1080p או 720p (מהיר וקל יותר; נבחר לבד במכשירים חלשים); שפת הכרטיסים (כשההזמנה בכמה שפות — כל אחת משפות ההזמנה; מתחילים בשפה הראשית שלה); מוזיקה — השיר של ההזמנה, "שיר אחר" (קובץ MP3/M4A/WAV שנשאר במחשב, עד 40MB), או בלי.
- הקצב נקרא במחשב: כל חיתוך נופל על ביט, השיר נחלש בסוף, והתנועה האיטית על כל תמונה לא חותכת אף פנים. כרטיס פתיחה וסיום בצבעים ובגופנים של ההזמנה (השמות, התאריך ו"תודה שחגגתם איתנו"), בגופן של ההזמנה לכל כתב — גם ערבית, רוסית ואמהרית — ובעברית ובערבית מימין לשמאל.
- "תצוגה מקדימה" מנגנת את הסרט בקטן עם השיר. "יצירת הסרט" מראה התקדמות, ואפשר לבטל. בדפדפן שמקודד H.264 (Chrome, Edge, Safari במחשב) הסרט נוצר מהר מזמן אמת כקובץ MP4; בדפדפן אחר הוא מוקלט בזמן אמת — צריך להשאיר את הלשונית פתוחה וגלויה עד הסוף.
- בסוף: "הורדה", ו"הוספה לגלריה" — הסרט עולה כפריט של המארחים ("הסרט שלכם" ברשימת הגלריה). אם מסמנים "להציג לאורחים בגלריה ובמסך האירוע" הוא מופיע אצל האורחים ובמסך; אחרת הוא נשמר מוסתר ואפשר להציג אותו אחר כך.
- תקלות: "הדפדפן הזה לא יכול ליצור וידאו" — נסו Chrome, Edge או Safari עדכניים במחשב. "לא הצלחנו לקרוא את השיר" — נסו קובץ אחר. הסרט קצר מהאורך שבחרתם — השיר קצר יותר, או שאין מספיק צילומים. "צריך לפחות 3 צילומים" — עוד אין מספיק תמונות מוצגות בגלריה.

## 21. "התמונות שאני בהן" — חיפוש לפי פנים בגלריה
- מה זה: כל אורח מצלם סלפי ומקבל אלבום אישי של התמונות בגלריה שהוא מופיע בהן, להורדה. כלול בחבילת VIP (תוכנית Business), ורק כשהאפשרות פעילה באתר (היא דורשת אישור משפטי, ולכן ייתכן שעוד לא זמינה). היא אף פעם לא פועלת מעצמה: בלשונית "גלריה", בכרטיס "התמונות שאני בהן", המארחים לוחצים "הפעלת החיפוש לפי פנים". באותו כרטיס: המצב, "הכנת החיפוש" ו"כיבוי ומחיקת קודי הפנים".
- פרטיות: האורח מסכים במפורש (תיבת סימון נפרדת) לפני הכל. הסלפי לא יוצא מהטלפון; רק "קוד פנים" (128 מספרים) נשלח לכל חיפוש, ולא נשמר ולא נרשם. מהתמונות נשמרים רק מיקום הפנים וקוד הפנים — בלי שמות ובלי חיתוכים. כל קודי הפנים נמחקים 30 יום אחרי האירוע, מיד כשהמארחים מכבים את החיפוש או מוחקים את הגלריה, ועם החשבון. פרטים ב־/privacy (סעיף 7ג).
- אצל האורח: "למצוא את התמונות שאני בהן" בעמוד הגלריה ← הסכמה ← סלפי (מצלמה או תמונה מהטלפון) ← האלבום ו"הורדת התמונות שלי". "לא להראות אותי בחיפושים של אחרים" מוציא את הפנים שלו מכל החיפושים (גם מתמונות שיעלו אחר כך). "לשכוח אותי" מוחק מיד את הפנים שלו מהחיפוש ואת קוד הפנים מהטלפון.
- הכנה: טלפון שהעלה תמונה מכין אותה לחיפוש לבד. "הכנת החיפוש" בכרטיס מכינה במחשב של המארחים את התמונות שעוד לא הוכנו (בדפדפן, בלי לשלוח תמונות), עם התקדמות ו"עצירה" — וממשיכה אחר כך מאותה נקודה.
- תקלות: "לא מצאנו פנים בתמונה" — סלפי מול המצלמה, באור טוב, בלי משקפי שמש. "לא מצאנו אותך עדיין" — אולי התמונות עוד לא הוכנו (בקשו מהמארחים "הכנת החיפוש") או שעוד לא עלו. "החיפוש נסגר" — עברו 30 יום מהאירוע והקודים נמחקו.

## 22. הגלריה בתוך ההזמנה ("הוספת סקשן" ← "גלריית האורחים")
- כשהאירוע כולל גלריה חיה, אפשר להוסיף להזמנה סקשן "גלריית האורחים" (אחד בהזמנה) עם כותרת וטקסט לפני האירוע ואחריו. לפני האירוע ובמהלכו יש בו כפתור (ובמסך רחב גם קוד QR) להעלאת תמונות לגלריה, עם הקישור האישי של האורח (הגלריה נפתחת בשפה שבה הוא קורא את ההזמנה); אחרי האירוע — "לאלבום". השינוי בין השלבים קורה לבד לפי התאריך והשעה של האירוע (מ־3 שעות לפני ועד 6 שעות אחרי הסיום).
- כשהגלריה כבויה או לא קיימת, הסקשן לא מוצג לאורחים. "קוד QR ליד הכפתור" בטופס הסקשן מציג או מסתיר את הקוד (במסך מחשב).

## 23. תובנות (לשונית "תובנות" של ההזמנה)
- מה זה: איך האורחים משתמשים בהזמנה — כמה ביקורים, כמה פתחו את ההזמנה, קראו עד הסוף, התחילו למלא אישור הגעה ואישרו; הזמן החציוני בדף; לפי שפה, לפי מקור (קישור אישי, הקישור המשותף, קוד QR, אחר) ולפי מכשיר; גרף לפי יום; קישורים אישיים שנפתחו; ההעלאות לגלריה. טווח: 7 ימים, 30 יום או מאז הפרסום. כלול בכל החבילות.
- פרטיות: בלי עוגיות ובלי לשמור שום דבר במכשיר של האורח; לא נשמרות כתובות IP או פרטי דפדפן; כשהדפדפן מבקש לא לעקוב (GPC / Do Not Track) לא נמדד כלום; רובוטים לא נספרים. רק סיכומים — אף פעם לא מי עשה מה. הרישום של כל ביקור נמחק אחרי 7 ימים. פרטים ב־/privacy (סעיף 7ד).
- למה המספרים לא תואמים בדיוק: אורחים שביקשו לא לעקוב לא נספרים, ואישורי הגעה שהמארחים הזינו בעצמם או שהגיעו מוואטסאפ לא נספרים כ"אישרו דרך הדף". המספרים מתעדכנים תוך דקות.

## 24. פנייה לצוות ("תמיכה", /app/support)
- מתי: כשהעוזר לא פתר את הבעיה, או בכל נושא שצריך בו אדם — תקלה, חיוב מסוים או החזר, בקשת פרטיות, נגישות, שיתוף פעולה. הצוות רואה את הפנייה ועונה בהקדם (לא מיד — אין צ׳אט חי).
- איך פותחים: "תמיכה" בסרגל הצד (בטלפון: "תמיכה" בסרגל התחתון, וגם בתפריט החשבון) ← "פנייה חדשה": נושא, סוג הפנייה (שאלה על המערכת, חיובים ותשלומים, פרטיות, נגישות, שיתופי פעולה, דיווח על תקלה, אחר), על איזו הזמנה (רשות) וההודעה ← "שליחת הפנייה".
- מהצ׳אט הזה: "לדבר עם נציג" בתחתית הצ׳אט פותח פנייה עם השיחה הזו מצורפת. לפני השליחה רואים בדיוק מה יישלח — הנושא, ההודעה (אפשר לשנות) וכל השיחה — ורק אז "שליחה לצוות".
- גם טופס יצירת הקשר (${c.site}/contact) פותח פנייה: מי שמחובר רואה אותה ב"תמיכה"; מבקר בלי חשבון מקבל את התשובה במייל ויכול להשיב לה ישירות.
- איפה התשובה: בעמוד הפנייה ב"תמיכה", ובמייל עם קישור לפנייה. העמוד מתעדכן מעצמו כשהצוות עונה, ופנייה עם תשובה חדשה מסומנת ("תשובה חדשה", ונקודה ליד "תמיכה" בתפריט).
- המצבים: "ממתינה לצוות" (הצוות עוד לא ענה), "נענתה" (הצוות ענה — אפשר להשיב), "סגורה". תשובה בפנייה סגורה פותחת אותה מחדש. "סגירת הפנייה" כשהבעיה נפתרה. פנייה שנענתה ולא הגיבו בה ${TICKETS.autoCloseDays} ימים נסגרת מעצמה (ותמיד אפשר לפתוח אותה מחדש בתשובה).
- מגבלות: עד ${TICKETS.openPerHour} פניות חדשות בשעה ועד ${TICKETS.repliesPerHour} הודעות בשעה. לא כותבים בפנייה סיסמאות, פרטי אשראי או קודים.
- פרטיות: הפנייה, ההודעות והשיחה עם העוזר שצורפה נשמרות, וצוות התמיכה בלבד רואה אותן; הן נמחקות שנתיים אחרי שהפנייה נסגרה. פרטים ב־/privacy (סעיף 7ה).

## 25. תכנון האירוע ("תכנון האירוע" בסרגל האירוע: משימות, תקציב, ספקים, פתקים ורעיונות)
- מה זה: מקום אחד לתכנון האירוע עצמו — משימות, תקציב, ספקים ופתקים ורעיונות. השלב מופיע רק כשהתכנון פעיל באתר, ולא בהזמנה מסוג "שמירת תאריך" (התכנון נעשה בהזמנה המלאה). הוא מופיע כשבחרו בכלי "תכנון האירוע" (באשף או ב"הוספה או הסרה של כלים"); על הכלי בסרגל: כמה משימות השבוע, או "בתהליך". אפשר להתחיל רק מתכנון, בלי הזמנה: "אירוע חדש" ← מסמנים רק "תכנון האירוע".
- ההקמה (פעם אחת, שלושה צעדים קצרים, אפשר לדלג על כל אחד): האירוע (הפרטים נלקחים מההזמנה, ובונים תוכנית מוכנה לסוג האירוע: חתונה, בר/בת מצווה וברית בתוכנית מלאה; אירוסין, חינה, בייבי שאוור, יום הולדת ואירוע חברה בתוכנית קלה. באירוע מסוג "אחר": רשימה ריקה, או — בחבילת Pro — "הצעה לפי תיאור" שמכינה טיוטה לאישור, או תבנית שלכם); אורחים ותקציב (מספר המוזמנים נלקח מהרשימה, והתקציב הכולל לא חובה); ורמת השילוב — "עצמאי", "מומלץ" (ברירת המחדל: ספקים ומשימות מעדכנים את התקציב, וכרטיס בסקירה) או "מלא" (גם עלויות לפי אורח ושולחן מהמוזמנים, האישורים וסידור השולחנות, ותשלומי היום ביום האירוע). אפשר לשנות בכל רגע ב"הגדרות", וכיבוי חיבור לא מוחק שום דבר.
- אין יותר "סקירה" נפרדת לתכנון: הצעד בתכנון (במסלול), המשימות של השבוע ומד התקציב נמצאים בבית האירוע (הכתובת /plan מובילה לשם אחרי ההקמה). אחרי האירוע התקציב הופך לסיכום: הוצאה סופית, מה שולם ודירוג ספקים — בלי תזכורות.
- משימות: ציר זמן (באיחור, השבוע, החודש, בהמשך), לפי קטגוריה או רשימה; "לטיפול עכשיו", "שלי", "עם עלות" ו"הוסתרו". מוסיפים משימה בשורה אחת עם Enter, מסמנים (עם "ביטול"), גוררים לשינוי סדר, ובפרטים: תאריך, אחראי, הערות וקישור לספק, לסעיף או לרעיון. משימות אוטומטיות — עיצוב, פרסום, רשימת מוזמנים, שליחה ואישורי הגעה (אותם חמשת הצעדים של "הדרך להזמנה מושלמת"), וגם דדליין האישורים, עדכון הכמות הסופית, סידור שולחנות ועמדת הכניסה — מסומנות לבד, עם כפתור "לביצוע". התאריכים מחושבים מתאריך האירוע; כשנשאר מעט זמן המשימות נדחסות לשבועות הקרובים, ומשימה שכבר לא רלוונטית מוצעת להסתרה. שינוי תאריך האירוע מציע "לעדכן את תאריכי היעד?" — משימות שקבעתם להן תאריך בעצמכם לא יזוזו. "ליומן" מייצא קובץ יומן (ICS), ולכל משימה יש "הוספה ל-Google Calendar".
- תקציב: למעלה "מד מהירות" — חצי עיגול עד 130% מהתקציב: ירוק עד 85%, צהוב 85%–100%, אדום מעל 100%. המחוג הראשי = מה שהתחייבתם (או ששולם) מתוך התקציב, מחוג מקווקו = המתוכנן, קו דק = מה ששולם; באמצע האחוז, "נשארו ₪X" או "חריגה של ₪X" ומשפט ("אתם בטוחים בתקציב" / "מתקרבים לגבול — שווה לבדוק" / "חרגתם מהתקציב"). לידו התקציב, התחייבנו, שולם, נשאר, ועלות לאורח (בשקלים שלמים) לפי מספר האורחים. "אורחים ושיטת חישוב": שלושה מספרים זה לצד זה — מה שהתקציב סופר, "הוזמנו ברשימה" ו"אנשים שאישרו הגעה". מאיפה לקחת את מספר האורחים: "לפי הרשימה" (ברירת המחדל: מי שאישר — לפי התשובה, מבוגרים וילדים; מי שעוד לא ענה — לפי מספר המוזמנים שלו; מי שענה שלא יגיע לא נספר — אותם מספרים כמו ברשימת המוזמנים ובסידור השולחנות), "מי שאישר הגעה" (רק התשובות), או "אורחים צפויים" (מספר משלכם, עם "סנכרון לרשימה" כשהוא שונה מהרשימה). מדים קטנים לכל קטגוריה (סגרנו מול תכננו, החורגות ראשונות; לחיצה פותחת את הקטגוריה; גם תצוגה כטבלה), "התשלומים הבאים" ב־30 הימים הקרובים עם "סימון כשולם", ו"מה אם?" — סליידרים למספר האורחים ומחיר המנה שמזיזים מד בזמן אמת בלי לשמור. חלוקת תקציב לקטגוריות לפי אחוזים נעשית בשקלים שלמים והעודף נכנס ל"אחר", כך שהסכום שווה בדיוק לתקציב. סעיף עובר: הערכה ← הצעה ← סגור ← שולם. לוח תשלומים (מקדמה, תשלום, יתרה, "תשלום ביום האירוע"). המחירים כוללים מע״מ. ייצוא ל-Excel וצירוף קבצים — ב-Pro.
- ספקים: שלבים — רעיון, יצרנו קשר, הצעת מחיר, סגרנו (ולא רלוונטי); "מה חסר" לפי סוג האירוע; השוואת הצעות באותה קטגוריה; חיוג ווטסאפ בלחיצה. סגירת ספק מציעה בלחיצה: סעיף בתקציב, לוח תשלומים לפי תנאי התשלום, ומשימות המשך (עם "ביטול").
- פתקים ורעיונות: כרטיסי טקסט, קישור (עם תצוגה מקדימה), תמונה ורשימה; תגיות, צבעים, נעיצה וחיפוש; "הפוך ל…" משימה, ספק או סעיף תקציב. בחבילת Pro: "סכם והצע צעדים" מכין טיוטה לאישור.
- חבילות: הסקשן כולו חינם. Pro: הצעה לפי תיאור ו"סכם והצע צעדים", ייצוא ל-Excel, קבצים מצורפים. Business: שמירת תוכנית כתבנית פרטית (עד 20) והתחלת אירועים חדשים ממנה. תזכורות: סיכום שבועי במייל (אפשר לכבות ב"הגדרות").
- פרטיות: התכנון רק של בעל ההזמנה; אורחים לא רואים שום דבר ממנו. פרטים ב־/privacy (סעיף 7ו).
- תקלות: "אין לשונית תכנון" — ההזמנה היא "שמירת תאריך", או שהתכנון כבוי לאירוע (אפשר להפעיל מחדש) או באתר. "המספרים בתקציב לא משתנים עם האורחים" — בדקו ב"הגדרות" שהשילוב כולל את המוזמנים ואישורי ההגעה (רמת "מלא"), ובתקציב שבסיס האורחים אינו ידני.
`.trim();
}
